import{z as d,x as s,o as e,c as B,q as r,j as l,D as t,d as E,s as i,S as n}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"自动微分与计算图","description":"","frontmatter":{"title":"自动微分与计算图","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/autograd-graph.md","filePath":"llm/autograd-graph.md","lastUpdated":1791063341000}'),p={name:"llm/autograd-graph.md"};function A(c,a,m,h,D,_){const o=s("Mermaid");return e(),B("div",null,[a[2]||(a[2]=r('<h1 id="自动微分与计算图" tabindex="-1">自动微分与计算图 <a class="header-anchor" href="#自动微分与计算图" aria-label="Permalink to &quot;自动微分与计算图&quot;">​</a></h1><div class="epigraph"><p>反向模式把标量损失对全体输入的导数，收成一次与计算图拓扑相反的扫描；每条原语只提供局部 Jacobian-向量积。</p><footer>—— 据 Rumelhart, Hinton &amp; Williams, Nature 1986；综述见 Baydin et al., Automatic Differentiation in Machine Learning, JMLR 2018</footer></div><p><a href="/llm/attention-backward">上一课</a>把 softmax 注意力的 \\(dQ,dK,dV\\) 手写清楚了。缺口立刻出现：一层注意力只是图上的一个子图，还有嵌入、RMSNorm、FFN、残差与交叉熵。逐算子手推 Jacobian 既不能随架构改动，也容易漏掉广播与掩码。本课把「反传」从一条注意力公式换成<strong>计算图上的反向模式自动微分</strong>。后课的初始化假定：框架会按图把梯度送回每一个叶子参数，你要管的是尺度，不是有没有链式法则。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>前向把张量运算排成有向无环图：节点是值，边是原语（矩阵乘、softmax、加减、gather）。训练要的是 \\(\\partial\\mathcal{L}/\\partial\\theta\\)，其中 \\(\\theta\\) 是全部叶子。符号微分会把表达式胀成指数级；数值微分对每个参数前向两次，十亿参数不可行。反向模式（即深度学习里的反传）只要求损失是标量：先正向记录中间值或重算所需的检查点，再从 \\(\\partial\\mathcal{L}/\\partial\\mathcal{L}=1\\) 逆拓扑传播向量-Jacobian 积。</p><p><a href="/llm/attention-backward">注意力反向</a> 已是这条规则在一个子图上的实例。本课的缺口不是再写一遍 \\(dS\\)，而是：<strong>图如何决定保存什么、何时释放、广播如何把梯度求和回同一缓冲</strong>。漏掉 residual 的加法边，底层嵌入会少一半梯度；漏掉 embedding gather 的 scatter-add，被多个位置共用的 token 只收到最后一次写入。</p><p><span class="marginnote">PyTorch 一类动态图在前向现场把 Function 压栈；静态图则先编译再跑。对你要写的 Transformer，二者的数学对象相同，差别在控制流与重算策略。Paszke 等人把动态图写成可运行的原语，并不另造一种导数定义。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>每个原语 \\(y=f(x)\\) 必须实现：已知 \\(v=\\partial\\mathcal{L}/\\partial y\\)，求 \\(v^\\top Df(x)\\)，即 VJP。矩阵乘 \\(Y=XW\\) 的 VJP 是 \\(dX=dY W^\\top\\)、\\(dW=X^\\top dY\\)，与手推公式同类。加法 \\(y=a+b\\) 把 \\(dy\\) 原样发给 \\(a\\) 和 \\(b\\)。广播把较瘦的那个输入上的梯度沿被扩张的轴求和。<code>gather</code> 的反向是 <code>scatter_add</code>：同一 index 出现多次，梯度相加。</p>',9)),(e(),l(n,null,{default:t(()=>[i(o,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20LR%0A%20%20DY%5B%22%E5%90%8C%E4%B8%80%E6%9D%A1%E4%B8%8A%E6%B8%B8%E6%A2%AF%E5%BA%A6%20dY%22%5D%20--%3E%20ADD%5B%22%E7%BB%8F%E8%BF%87%E5%8A%A0%E6%B3%95%E8%BE%B9%20a%2Bb%22%5D%0A%20%20ADD%20--%3E%20DA%5B%22a%E3%80%81b%20%E5%90%84%E6%8B%BF%E4%B8%80%E4%BB%BD%E5%8E%9F%E6%A0%B7%20dy%22%5D%0A%20%20DY%20--%3E%20BC%5B%22%E7%BB%8F%E8%BF%87%E5%B9%BF%E6%92%AD%E8%BE%B9%22%5D%0A%20%20BC%20--%3E%20BS%5B%22%E7%98%A6%E8%BE%93%E5%85%A5%E4%BE%A7%E6%B2%BF%E6%89%A9%E5%BC%A0%E8%BD%B4%E6%B1%82%E5%92%8C%22%5D%0A%20%20DY%20--%3E%20GA%5B%22%E7%BB%8F%E8%BF%87%20gather%20%E8%BE%B9%22%5D%0A%20%20GA%20--%3E%20SA%5B%22%E5%8F%8D%E5%90%91%20scatter_add%EF%BC%9A%E5%90%8C%20index%20%E7%9B%B8%E5%8A%A0%22%5D%0A%20%20DY%20--%3E%20DET%5B%22%E6%92%9E%E4%B8%8A%20detach%22%5D%0A%20%20DET%20--%3E%20Z%5B%22%E5%9C%A8%E6%AD%A4%E6%88%AA%E6%96%AD%EF%BC%8C%E4%B8%8B%E6%B8%B8%E4%B8%BA%200%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[E(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=r('<p><span class="marginnote">VJP 翻译过来就是「把上游梯度从输出端乘回这一层的局部导数」。关键在于不需要写出完整 Jacobian：矩阵乘 \\(Y=XW\\) 只拿现成的 \\(X\\) 和 \\(dY\\) 就能算出 \\(dW=X^\\top dY\\)，中间矩阵从不显式成形——这是反向模式不会指数膨胀的原因。</span></p><p>实现上通常有两类检查点。默认：保存前向张量供反向读取，显存随深度与序列长涨。梯度检查点：只保存若干边界，中间段反向时重算前向。FlashAttention 是核内重算，检查点是层间重算，可以叠用，但都改变「图上哪些边被物化」，不改变 VJP 定义。</p><p>混合精度把部分节点改成 BF16/FP16，反向仍可能在 FP32 累加器里做。这是数值策略，不是另一种微分。若某节点在前向被 <code>detach</code> 或 <code>stop_gradient</code>，图在那里断开，下游参数收不到这条路径的梯度——MoE 负载均衡有时故意这么做，必须写进配方，不能当框架 bug。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>反向模式的代价：对标量损失，一次反传得到全体 \\(\\partial\\mathcal{L}/\\partial\\theta\\)，时间与前向量级相同（常数因子，通常 1–2 倍于前向），额外存储与「保存的激活」成正比。前向模式 AD 适合输入维远小于输出维，语言模型正好相反，所以训练不用前向模式扫参数。</p><p><span class="marginnote">代个数字看两种模式的差别：前向模式一次扫描只得到「一个输入方向」上的导数，\\(N=10^9\\) 个参数就要扫 \\(10^9\\) 遍；反向模式一次逆拓扑扫描拿到全部参数梯度，代价只相当于跑 1-2 次前向。「多输入、少输出用反向」说的就是这件事——损失恰好是那唯一的输出。</span></p><p>拓扑顺序必须尊重数据依赖。流水线并行把图画成跨设备的阶段，微批之间的激活仍是边；ZeRO 把叶子参数切到不同 rank，反向时梯度在切分后的叶子上做 All-Reduce 或 Reduce-Scatter。这些是同一张逻辑图的切分，VJP 公式不改。错的切分表现为「某一层梯度恒为零」或「范数少乘了 \\(\\sqrt{N}\\)」，要用后课的梯度范数监控来抓，而不是改 softmax 公式。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>自动微分不保证梯度有用。饱和的 softmax、被 mask 成 0 的位置、以及 <code>float16</code> 下变成 Inf 的中间值，图仍会返回一个数，那个数可以是 0 或 NaN。本课只保证：<strong>若前向定义了 \\(f\\)，反向实现了对应 VJP，得到的就是 \\(\\nabla f\\)</strong>（在浮点误差内）。尺度、裁剪、跳过坏 batch，是后课。</p><p><span class="marginnote">常见误区：框架返回了梯度不代表梯度健康。中间值溢出成 Inf、softmax 饱和、位置被 mask 掉，反向照样「正常」返回一个数——可能正好是 0 或 NaN。所以工程惯例是先盯梯度范数和损失曲线，确认数值健康，再谈调优化器。</span></p><p>不要用手写注意力反向去替代框架；手写的用途是审查融合核。若融合核的 VJP 与 <a href="/llm/attention-backward">注意力反向</a> 不一致，那是实现错误，不是「另一种注意力」。二阶量（Hessian-向量积）可以再在此图上套一层前向-over-反向，本课不进入二阶优化。</p>',11)),(e(),l(n,null,{default:t(()=>[i(o,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E5%8F%B6%E5%AD%90%E5%8F%82%E6%95%B0%22%5D%20--%3E%20F%5B%22%E5%89%8D%E5%90%91%E5%8E%9F%E8%AF%AD%22%5D%0A%20%20F%20--%3E%20L%5B%22%E6%A0%87%E9%87%8F%E6%8D%9F%E5%A4%B1%22%5D%0A%20%20L%20--%3E%20VJP%5B%22%E9%80%86%E6%8B%93%E6%89%91%20VJP%22%5D%0A%20%20VJP%20--%3E%20G%5B%22%E5%8F%82%E6%95%B0%E6%A2%AF%E5%BA%A6%22%5D%0A%20%20F%20--%3E%20SAVE%5B%22%E4%BF%9D%E5%AD%98%E6%88%96%E6%A3%80%E6%9F%A5%E7%82%B9%22%5D%0A%20%20SAVE%20--%3E%20VJP%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[E(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=r('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>反向模式 AD 把标量损失的梯度收成一次逆拓扑扫描；每个原语只提供 VJP。</li><li>注意力手推公式是图上一个子图；残差、广播、gather 的求和边同样不可漏。</li><li>保存激活、层间检查点、核内重算改的是存储，不改导数定义。</li><li>图断开（detach）与混合精度是配方决策，必须显式。</li><li>有梯度不等于梯度可用；尺度留给初始化与稳定性课。</li><li>出处：Rumelhart, Hinton &amp; Williams, <em>Nature</em> 1986；Baydin et al., <em>JMLR</em> 2018；Paszke et al., PyTorch, NeurIPS 2019。</li></ul>',2))])}const F=d(p,[["render",A]]);export{u as __pageData,F as default};
